begin;
-- Inferential field labels like "اطلاعات کشنده" were generated by an
-- unconstrained word-cluster fallback. Hide low-quality, never-verified
-- fields without deleting any definitions or customer values.
update public.crm_field_definitions f
set enabled=false,ask_enabled=false
where f.key like 'learned_%' and f.label like 'اطلاعات %'
and not exists (
 select 1 from public.crm_information_states s
 where s.tenant_id=f.tenant_id and s.field_id=f.id and s.status='confirmed'
);
-- The scanner creates ONLY pending proposals with evidence; it does not
-- approve facts, fill profiles, or enable new field definitions.
select cron.schedule('sima_learning_evidence_scan','*/30 * * * *','select public.crm_learning_scan_batch();');
commit;